input.command:
mkdir -p /tmp/plantation-tools && cat > /tmp/plantation-tools/dump.mjs <<'EOF'
// usage: node dump.mjs build.nbt x0 y0 z0 x1 y1 z1  -> prints non-air cells per y layer as a z-row grid with a legend
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [file, ...n] = process.argv.slice(2);
const [x0, y0, z0, x1, y1, z1] = n.map(Number);
const g = load(file);
const short = (b) => (b || "minecraft:air").replace("minecraft:", "");
for (let y = y0; y <= y1; y++) {
  console.log(`y=${y}`);
  for (let z = z0; z <= z1; z++) {
    let row = "";
    for (let x = x0; x <= x1; x++) {
      const c = g.get(x, y, z);
      const b = short(c?.block);
      row += b === "air" || b === "cave_air" ? "." : b.slice(0, 1);
    }
    console.log(String(z).padStart(3) + " " + row);
  }
}
