    if (below && /slab$/.test(strip(below.block)) && below.state?.type === "bottom" && !HANGS.test(b) && !(/lantern$/.test(b) && String(s.hanging) === "true") && !(/trapdoor$/.test(b) && String(s.open) === "true"))
      add("on a bottom slab", c.pos, `${b} stands on a bottom slab: half a block of air under it (make the slab a top slab or a full block, or drop the ${b} onto the slab's level)`);
    // 2. floor decor with nothing to stand on
    else if (STANDS.test(b) && !(/lantern$/.test(b) && String(s.hanging) === "true") && !topFace(below))
      add("floating", c.pos, `${b} has ${below ? strip(below.block) + (below.state?.type ? ` (${below.state.type})` : "") : "air"} under it: it needs a top face to stand on`);
    // hanging lanterns hang from something
    if (/lantern$/.test(b) && String(s.hanging) === "true" && AIR(at(x, y + 1, z)?.block))
      add("floating", c.pos, `${b} hangs from air: give it a chain or a block above`);
    // 3. beds come in two halves, head ahead of foot in the bed's facing, same colour and facing
    if (/_bed$/.test(b)) {
      const d = DIRS[s.facing] ?? [0, 0, 0], sign = s.part === "foot" ? 1 : -1, o = at(x + d[0] * sign, y, z + d[2] * sign);
      if (!o || strip(o.block) !== b || o.state?.facing !== s.facing || o.state?.part === s.part)
    else if (dead.length >= 6) issues.push({ kind: "hallway to nowhere", at: dead[0].split(",").map(Number), room: r.name, what: `${r.name}: ${dead.length} floor cells of dead end that no walk between its ${openings.length} openings passes (from ${dead[0]}): end the hall at its last door, or put a door, a window seat or a cupboard at its end` });
  }
  const byKind = {};
  for (const i of issues) byKind[i.kind] = (byKind[i.kind] ?? 0) + 1;
  return { issues, byKind, ok: issues.length === 0 };
}

export function formatFit(r, { max = 6 } = {}) {
  if (r.ok) return "fit: OK (nothing on bottom slabs, nothing floating, beds whole, shutters on walls, bookshelves in their place, every hall leads somewhere)";
  const lines = [`fit: ${r.issues.length} issues: ${Object.entries(r.byKind).map(([k, n]) => `${n} ${k}`).join(", ")}`];
  for (const kind of Object.keys(r.byKind)) for (const i of r.issues.filter((x) => x.kind === kind).slice(0, max)) lines.push(`  [${kind}] ${i.at?.join(",") ?? ""}  ${i.what}`);
  return lines.join("\n");
}

