  ];
  for (const [lx, lz, f] of shutters) {
    const [x, z] = at(lx, lz);
    shutter(w, [x, y0 + 1, z], turn(f), "dark_oak", { height: 3 });
  }
  // hip roof over the main block and porch, half pitch, one-cell overhang
