  const xs = corners.map((c) => c[0]), zs = corners.map((c) => c[1]);
  hipRoof(w, { footprint: [[Math.min(...xs), Math.min(...zs), Math.max(...xs), Math.max(...zs)]], y: y0 + 6, material: "deepslate_tile", pitch: 0.5, overhang: 1 });
  return w.result();

