// The roof tool hangs its truss ties under the roof's underside. Where that underside is a bottom slab, the tie stands
// half a block over air (fit: "on a bottom slab"). Fill each such slab to a whole block so the tie has a whole face.
function fillTieSlabs(g) {
  let n = 0;
  for (let x = 0; x < 96; x++) for (let y = 1; y < 32; y++) for (let z = 0; z < 96; z++) {
    if (!/stripped_spruce_log$/.test(g.blockAt(x, y, z))) continue;
    const below = g.get(x, y - 1, z);
    if (below && /deepslate_tile_slab$/.test(below.block) && below.state?.type === "bottom") {
      g.set(x, y - 1, z, "deepslate_tiles");
      n++;
    }
  }
  return n;
}

export function build(g) {
  // ---- chimney stacks above the plate: through the roof, capped with a signal fire. Stacks start at y1 so the top
