// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// TRUSSES: the frame that holds a pitched roof up, seen from inside (a loft, an open hall, a barn). Without it the
// slates float over an empty attic. For each footprint rect it measures the finished roof (span between the walls,
// rise from the tie to the underside at the ridge), lets the truss simulation (truss-sim.mjs) choose the style,
// spacing and member thickness that carries the roof's weight and snow with the least timber, then draws exactly that
// truss: the top chord (principal rafters) along the roof's underside, the tie (or a collar 2 up, with posts to the
// plates, over a floor you walk on), the web members between the panel points, a purlin under every top panel point
// and the ridge beam the whole length; the trusses evenly spaced between the gables. Air only: it never cuts a roof,
// a window or a part's work.
//   trussPlan(grid, { footprint: [[x0,z0,x1,z1], ...], y, ridgeAxis, style: "auto", material, collar, every })
//     -> { blocks: [[x, y, z, block, state], ...], reports: [{ rect, sim, pick }] }
import { simulateRoof, trussGeometry, formatSim, evaluateTruss } from "./truss-sim.mjs";

const strip = (n) => String(n ?? "air").replace(/^minecraft:/, "");
const AIR = (b) => /(^|_)air$/.test(strip(b));
const AXIAL = /log$|wood$|stem$|hyphae$|basalt$|pillar$|bamboo_block$/;

export function trussPlan(g, { footprint, y, ridgeAxis, style = "auto", material = "stripped_spruce_log", collar, every } = {}) {
  if (!footprint?.length || y == null) throw new Error("trusses: footprint (the wall rects) and y (the eave course) are required");
  const blocks = [], reports = [], seen = new Set();
  const air = (x, yy, z) => g.inBounds(x, yy, z) && AIR(g.blockAt(x, yy, z));
